package postcode

import (
	_ "embed"
	"encoding/json"
	"fmt"
)

// The JSON is generated by cmd/postcodeconvert and embedded so the server
// binary needs no data files at runtime.
//
//go:embed data/sectors.json
var sectors []byte

// LoadTable returns the embedded postcode -> region table.
func LoadTable() (*Table, error) {
	var t Table
	if err := json.Unmarshal(sectors, &t); err != nil {
		return nil, fmt.Errorf("decode postcode table: %w", err)
	}
	return &t, nil
}
